//! Original AF5670 owner target/value/clock setup; progression is separate.
use std::collections::{BTreeMap,BTreeSet};
use crate::{audio_bus_bank::Error,audio_plugin_factory::Memory};
use crate::audio_path_source_virtual_cleanup::{get,put};
#[derive(Clone,Copy,Debug)]pub struct Context{pub clock:u32,pub frame_quantum:u32,pub conversion_cache:u32}
pub(crate) fn gain(m:&mut BTreeMap<u32,Memory>,dead:&BTreeSet<u32>,bits:u32,c:Context)->Result<u32,Error>{
 let db=f32::from_bits(bits);if db*0.05 < -37.0{return Ok(0);}
 let flag=get(m,dead,c.conversion_cache.wrapping_add(4),4)?;if flag&1==0{put(m,dead,c.conversion_cache,4,0x4bd49a78)?;put(m,dead,c.conversion_cache.wrapping_add(4),4,flag|1)?;}else if get(m,dead,c.conversion_cache,4)?!=0x4bd49a78{return Err(Error::Backend("property conversion cache multiplier is unqualified"));}
 Ok(crate::audio_gain::native_extended_bits(bits))
}
/// Update the canonical owner bytes; same tagged key shortens remaining time.
/// No valid/finished phase is invented: AF5670 does not advance the transition.
pub fn update(m:&mut BTreeMap<u32,Memory>,dead:&BTreeSet<u32>,owner:u32,new_type:u32,value_bits:u32,duration:u32,curve:u32,operation:u32,c:Context)->Result<(),Error>{
 let old_type=get(m,dead,owner,4)?;let flags=get(m,dead,owner.wrapping_add(52),1)?;put(m,dead,owner,4,new_type)?;
 if flags&2!=0{let initial=get(m,dead,owner.wrapping_add(12),4)?;put(m,dead,owner.wrapping_add(4),4,initial)?;if flags&1!=0{let initial=gain(m,dead,initial,c)?;put(m,dead,owner.wrapping_add(4),4,initial)?;}}
 let mut target=if flags&1!=0{f32::from_bits(gain(m,dead,value_bits,c)?)}else{f32::from_bits(value_bits)};
 if operation==2{let previous=f32::from_bits(get(m,dead,owner.wrapping_add(8),4)?);target=if flags&1!=0{target*previous}else{target+previous};}put(m,dead,owner.wrapping_add(8),4,target.to_bits())?;
 let start=f32::from_bits(get(m,dead,owner.wrapping_add(4),4)?);let actual_curve=if target>start||curve==3||curve==5{curve}else{8u32.wrapping_sub(curve)};put(m,dead,owner.wrapping_add(44),4,actual_curve)?;
 let current=get(m,dead,c.clock.wrapping_add(124),4)?;let numerator=duration.wrapping_sub(1).wrapping_add(c.frame_quantum)as i32;let ticks=numerator.checked_div(c.frame_quantum as i32).ok_or(Error::Backend("native property duration division fault"))?as u32;
 if old_type==new_type && new_type&0x0f000000!=0{let remaining=get(m,dead,owner.wrapping_add(16),4)?.wrapping_sub(current).wrapping_add(get(m,dead,owner.wrapping_add(20),4)?);put(m,dead,owner.wrapping_add(28),4,current)?;put(m,dead,owner.wrapping_add(16),4,current)?;put(m,dead,owner.wrapping_add(20),4,remaining.min(ticks))?;}
 else{put(m,dead,owner.wrapping_add(28),4,current)?;put(m,dead,owner.wrapping_add(16),4,current)?;put(m,dead,owner.wrapping_add(20),4,ticks)?;}Ok(())
}
#[cfg(test)]mod tests{
 use super::*;use serde_json::{Value,json};
 fn bytes(s:&str)->Vec<u8>{(0..s.len()).step_by(2).map(|i|u8::from_str_radix(&s[i..i+2],16).unwrap()).collect()}
 fn hex(b:&[u8])->String{b.iter().map(|v|format!("{v:02x}")).collect()}
 #[test]fn audio_path_property_owner_update_matches1200_native_flags_raw_db_quiet_nan_negative_zero_same_tag_duration_shrink_signed_division_clock_cache_and_all_owner_bytes_cases(){let p:Value=serde_json::from_str(&crate::audio_test_fixture("data/4.20/audio_path_property_owner_update_preparation.json")).unwrap();assert_eq!(p["passed"],true);assert_eq!(p["case_count"],1200);for(i,row)in p["cases"].as_array().unwrap().iter().enumerate(){let mut m:BTreeMap<u32,Memory>=[("owner",0x40001000),("clock",0x40002000),("conversion_cache",0x14a7970)].into_iter().map(|(n,r)|(r,Memory{reference:r,raw:bytes(row["before"][n].as_str().unwrap())})).collect();update(&mut m,&BTreeSet::new(),0x40001000,row["new_type"].as_u64().unwrap()as u32,row["value_bits"].as_u64().unwrap()as u32,row["duration"].as_u64().unwrap()as u32,4,row["operation"].as_u64().unwrap()as u32,Context{clock:0x40002000,frame_quantum:48,conversion_cache:0x14a7970}).unwrap();assert_eq!(json!({"owner":hex(&m[&0x40001000].raw),"clock":hex(&m[&0x40002000].raw),"conversion_cache":hex(&m[&0x14a7970].raw)}),row["after"],"all exact owner/clock/cache bytes {i}");}} #[test]fn audio_path_property_owner_update_matches128_native_extended_gain_high_values_infinite_quiet_signaling_nan_silence_and_all_cache_bytes_cases(){let p:Value=serde_json::from_str(&crate::audio_test_fixture("data/4.20/audio_path_property_owner_gain_boundaries_preparation.json")).unwrap();assert_eq!(p["passed"],true);assert_eq!(p["case_count"],128);for(i,row)in p["cases"].as_array().unwrap().iter().enumerate(){let mut m:BTreeMap<u32,Memory>=[("owner",0x40001000),("clock",0x40002000),("conversion_cache",0x14a7970)].into_iter().map(|(n,r)|(r,Memory{reference:r,raw:bytes(row["before"][n].as_str().unwrap())})).collect();update(&mut m,&BTreeSet::new(),0x40001000,row["new_type"].as_u64().unwrap()as u32,row["value_bits"].as_u64().unwrap()as u32,row["duration"].as_u64().unwrap()as u32,4,row["operation"].as_u64().unwrap()as u32,Context{clock:0x40002000,frame_quantum:48,conversion_cache:0x14a7970}).unwrap();assert_eq!(json!({"owner":hex(&m[&0x40001000].raw),"clock":hex(&m[&0x40002000].raw),"conversion_cache":hex(&m[&0x14a7970].raw)}),row["after"],"all exact owner/clock/cache bytes {i}");}} #[test]fn audio_path_property_owner_update_matches160_native_x87_extended_sum_rounding_tiny_signed_subnormal_gain_integer_truncation_and_all_bytes_cases(){let p:Value=serde_json::from_str(&crate::audio_test_fixture("data/4.20/audio_path_property_owner_gain_precision_preparation.json")).unwrap();assert_eq!(p["passed"],true);assert_eq!(p["case_count"],160);for(i,row)in p["cases"].as_array().unwrap().iter().enumerate(){let mut m:BTreeMap<u32,Memory>=[("owner",0x40001000),("clock",0x40002000),("conversion_cache",0x14a7970)].into_iter().map(|(n,r)|(r,Memory{reference:r,raw:bytes(row["before"][n].as_str().unwrap())})).collect();update(&mut m,&BTreeSet::new(),0x40001000,row["new_type"].as_u64().unwrap()as u32,row["value_bits"].as_u64().unwrap()as u32,row["duration"].as_u64().unwrap()as u32,4,row["operation"].as_u64().unwrap()as u32,Context{clock:0x40002000,frame_quantum:48,conversion_cache:0x14a7970}).unwrap();assert_eq!(json!({"owner":hex(&m[&0x40001000].raw),"clock":hex(&m[&0x40002000].raw),"conversion_cache":hex(&m[&0x14a7970].raw)}),row["after"],"all exact owner/clock/cache bytes {i}");}}
}
